<?php
require_once 'inc/db.php';require_once 'inc/auth.php';
$where=(int)$_SESSION['role_id']===4?' WHERE r.reported_by=? AND ': ' WHERE ';
$sql='SELECT r.report_id,r.report_code,r.location_name,r.latitude,r.longitude,r.severity,r.status,dt.type_name FROM tbl_road_reports r JOIN tbl_damage_types dt ON dt.type_id=r.damage_type_id'.$where.'r.latitude IS NOT NULL AND r.longitude IS NOT NULL';
$s=$db->prepare($sql);$s->execute((int)$_SESSION['role_id']===4?[$_SESSION['user_id']]:[]);$points=$s->fetchAll(PDO::FETCH_ASSOC);
$severityCounts=['Critical'=>0,'High'=>0,'Medium'=>0,'Low'=>0];foreach($points as $point){if(isset($severityCounts[$point['severity']]))$severityCounts[$point['severity']]++;}
$activeCount=count(array_filter($points,fn($p)=>!in_array($p['status'],['Resolved','Rejected'],true)));
$priorityPoints=array_values(array_filter($points,fn($p)=>in_array($p['severity'],['Critical','High'],true)));usort($priorityPoints,fn($a,$b)=>array_search($a['severity'],['Critical','High','Medium','Low'])<=>array_search($b['severity'],['Critical','High','Medium','Low']));
$page_title='GIS Damage Map';$breadcrumb='Monitoring';include 'inc/links.php';include 'inc/header.php';?>
<div class="inner-wrapper"><?php include 'inc/sidebar.php';?><section role="main" class="content-body"><?php include 'inc/inner-header.php';?>
<div class="map-summary-grid"><div><span class="map-stat-icon mapped"><i class="fa fa-map-marker"></i></span><strong><?php echo count($points);?></strong><small>Mapped reports</small></div><div><span class="map-stat-icon active"><i class="fa fa-wrench"></i></span><strong><?php echo $activeCount;?></strong><small>Active issues</small></div><div><span class="map-stat-icon urgent"><i class="fa fa-exclamation-triangle"></i></span><strong><?php echo $severityCounts['Critical']+$severityCounts['High'];?></strong><small>High-risk locations</small></div><div><span class="map-stat-icon resolved"><i class="fa fa-check"></i></span><strong><?php echo count($points)-$activeCount;?></strong><small>Closed locations</small></div></div>
<section class="panel map-workspace"><header class="panel-heading"><div><span class="panel-overline">Geographic intelligence</span><h2 class="panel-title">Live road damage map</h2></div><div class="map-filters" role="group" aria-label="Filter map markers"><button class="active" data-severity="All">All <b><?php echo count($points);?></b></button><button data-severity="Critical"><i class="dot critical"></i> Critical</button><button data-severity="High"><i class="dot high"></i> High</button><button data-severity="Medium"><i class="dot medium"></i> Medium</button><button data-severity="Low"><i class="dot low"></i> Low</button></div></header><div class="panel-body"><div class="map-layout"><div class="map-main"><div class="map-shell"><div id="map"></div></div><div class="map-foot"><span><i class="fa fa-crosshairs"></i> Select a marker for its report summary</span><button type="button" id="resetMap"><i class="fa fa-expand"></i> Fit all locations</button></div></div><aside class="map-priority-list"><div class="map-list-heading"><span class="panel-overline">Maintenance focus</span><h3>Priority locations</h3><small>Critical and high-severity reports</small></div><div id="priorityList"><?php foreach(array_slice($priorityPoints,0,6) as $p):?><a href="view_report.php?id=<?php echo (int)$p['report_id'];?>" data-severity="<?php echo e($p['severity']);?>"><span class="map-list-marker <?php echo strtolower($p['severity']);?>"><i class="fa fa-map-marker"></i></span><div><strong><?php echo e($p['location_name']);?></strong><small><?php echo e($p['type_name']);?> &middot; <?php echo e($p['status']);?></small></div><?php echo severity_label($p['severity']);?></a><?php endforeach;?><?php if(!$priorityPoints):?><div class="map-empty"><i class="fa fa-check-circle"></i><span>No high-risk mapped issues.</span></div><?php endif;?></div><a href="all_reports.php" class="map-list-all">Open report queue <i class="fa fa-arrow-right"></i></a></aside></div></div></section>
</section></div><?php include 'inc/scripts.php';?><script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js" integrity="sha256-20nQCchB9co0qIjJZRGuk2/Z9VM+kNiyxNV1lvTlZBo=" crossorigin=""></script><script>
var map=L.map('map',{zoomControl:false}).setView([-1.9403,29.8739],8);L.control.zoom({position:'bottomright'}).addTo(map);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; OpenStreetMap contributors'}).addTo(map);
var colors={Low:'#269060',Medium:'#ed9a16',High:'#db702d',Critical:'#dc4b45'},points=<?php echo json_encode($points,JSON_HEX_TAG|JSON_HEX_AMP);?>,markers=[];
function escapeHtml(v){return String(v||'').replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c];});}
function popup(p){return '<div class="map-popup"><span class="popup-code">'+escapeHtml(p.report_code)+'</span><h4>'+escapeHtml(p.location_name)+'</h4><p>'+escapeHtml(p.type_name)+' <b class="popup-severity" style="color:'+colors[p.severity]+'">'+escapeHtml(p.severity)+'</b></p><span class="popup-status">'+escapeHtml(p.status)+'</span><a href="view_report.php?id='+Number(p.report_id)+'">Inspect report <i class="fa fa-arrow-right"></i></a></div>';}
points.forEach(function(p){var ll=[Number(p.latitude),Number(p.longitude)],marker=L.circleMarker(ll,{radius:10,color:'#fff',weight:3,fillColor:colors[p.severity]||'#777',fillOpacity:1}).bindPopup(popup(p),{minWidth:210});marker.report=p;markers.push(marker);marker.addTo(map);});
function visibleBounds(){var group=markers.filter(function(m){return map.hasLayer(m);});if(group.length)map.fitBounds(L.latLngBounds(group.map(function(m){return m.getLatLng();})),{padding:[38,38],maxZoom:14});else map.setView([-1.9403,29.8739],8);}
function filterMap(severity){markers.forEach(function(m){if(severity==='All'||m.report.severity===severity){m.addTo(map);}else{map.removeLayer(m);}});document.querySelectorAll('.map-filters button').forEach(function(b){b.classList.toggle('active',b.dataset.severity===severity);});document.querySelectorAll('#priorityList>a').forEach(function(a){a.style.display=(severity==='All'||a.dataset.severity===severity)?'flex':'none';});visibleBounds();}
document.querySelectorAll('.map-filters button').forEach(function(b){b.addEventListener('click',function(){filterMap(this.dataset.severity);});});document.getElementById('resetMap').addEventListener('click',visibleBounds);setTimeout(function(){map.invalidateSize();visibleBounds();},250);
</script>
